'use strict';
class BattleFeedback{
 constructor(e){this.e=e;this.cursor=e.events.at(-1)||null;this.enabled=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;try{const saved=localStorage.getItem('ashen-view-motion');if(saved!==null)this.enabled=saved==='on';}catch(err){}this.receipts=[];this.lastHit=0;this.trailTimers={};this.previous={team:0,enemy:0,enemyId:null};this.latestVictory=null;}
 sync(){this.cursor=this.e.events.at(-1)||null;}
 setEnabled(value){this.enabled=value;try{localStorage.setItem('ashen-view-motion',value?'on':'off');}catch(err){}document.querySelectorAll('.damage-number').forEach(n=>n.remove());}
 flash(side,critical=false){if(!this.enabled||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const target=document.getElementById(side==='team'?'teamHealthTrack':'enemyHealthTrack');target.getAnimations().forEach(a=>a.cancel());target.animate([{transform:'translateX(0)',filter:'brightness(1)'},{transform:'translateX(-2px)',filter:'brightness(.78)'},{transform:'translateX(2px)',filter:'brightness(1)'},{transform:'translateX(-1px)'},{transform:'translateX(0)'}],{duration:critical?230:170,easing:'ease-out'});}
 number(side,amount,critical=false,heal=false){if(!this.enabled)return;const lane=document.getElementById(side==='team'?'teamDamageLane':'enemyDamageLane');while(lane.children.length>=2)lane.firstElementChild.remove();const n=document.createElement('span');n.className='damage-number'+(critical?' critical':'')+(heal?' healing':'');n.textContent=(heal?'+':'−')+this.format(amount)+(critical?' 暴击':'');lane.append(n);setTimeout(()=>n.remove(),850);}
 format(n){return n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e4?(n/1e3).toFixed(1)+'k':Math.round(n).toLocaleString('zh-CN');}
 updateTrails(){const enemy=this.e.enemy,st=this.e.stats(),next={team:Math.max(0,this.e.s.hp/st.hp*100),enemy:enemy?Math.max(0,enemy.hp/enemy.maxHp*100):0,enemyId:enemy?.id||null};for(const side of ['team','enemy']){const trail=document.getElementById(side==='team'?'hpTrail':'enemyTrail');clearTimeout(this.trailTimers[side]);const same=side==='team'||next.enemyId===this.previous.enemyId||!next.enemyId,old=this.previous[side];if(this.enabled&&same&&next[side]<old){trail.style.transition='none';trail.style.width=old+'%';this.trailTimers[side]=setTimeout(()=>{trail.style.transition='width .38s ease-out';trail.style.width=next[side]+'%';},90);}else{trail.style.transition='none';trail.style.width=next[side]+'%';}}this.previous=next;}
 render(){const list=this.e.events;const index=this.cursor?list.indexOf(this.cursor):-1;const fresh=this.cursor&&index<0?[]:list.slice(index+1);this.cursor=list.at(-1)||null;const hits={team:{amount:0},enemy:{amount:0}},drops=[];for(const event of fresh){const d=event.data;if(!d)continue;if(d.kind==='hit'){hits[d.side].amount+=d.amount;hits[d.side].critical=hits[d.side].critical||d.critical;hits[d.side].heal=(hits[d.side].heal||0)+(d.heal||0);}else if(d.kind==='drop'||d.kind==='recruit')drops.push(d);else if(d.kind==='victory')this.latestVictory={...d,at:Date.now()};}for(const side of ['team','enemy']){const h=hits[side];if(h.amount){this.flash(side,h.critical);this.number(side,h.amount,h.critical);if(h.heal)this.number('team',h.heal,false,true);}}this.updateTrails();if(drops.length)this.receipts=([...this.receipts,...drops.map(d=>({...d,expires:Date.now()+6500}))]).slice(-3);this.receipts=this.receipts.filter(d=>d.expires>Date.now());this.renderDrops();if(this.latestVictory&&Date.now()-this.latestVictory.at<4500){document.getElementById('battleOutcome').textContent='战斗胜利 · 金币 +'+this.format(this.latestVictory.gold)+' · '+this.latestVictory.name;}else document.getElementById('battleOutcome').textContent=this.e.s.mode==='combat'?'正在交战':'等待下一场战斗';}
 renderDrops(){const box=document.getElementById('dropReceipts'),key=this.receipts.map(d=>d.label+d.expires).join('|');if(box.dataset.key===key)return;box.dataset.key=key;box.replaceChildren();if(!this.receipts.length){const hint=document.createElement('span');hint.className='drop-empty';hint.textContent='掉落物品会在此短暂展示';box.append(hint);return;}for(const d of this.receipts){const item=document.createElement('span');item.className='loot-receipt '+(d.type||'recruit')+(this.enabled?' has-motion':'');const type=document.createElement('small');type.textContent={equipment:'装备',material:'材料',special:'特殊',recruit:'招募'}[d.type||'recruit'];const label=document.createElement('b');label.textContent=d.label;item.append(type,label);box.append(item);}}
}
